(()=>{const $=id=>document.getElementById(id);if(!$('runDiagnostics'))return;let current;
function progress(done,total,label){const percent=Math.round(done/total*100);$('diagnosticProgress').hidden=false;$('diagnosticProgressBar').setAttribute('aria-valuenow',percent);$('diagnosticProgressBar').setAttribute('aria-valuetext',label+' · '+done+' of '+total+' steps');$('diagnosticProgressFill').style.width=percent+'%';$('diagnosticProgressPercent').textContent=percent+'%';$('diagnosticProgressLabel').textContent=label;$('diagnosticProgressSteps').textContent=done+' / '+total+' steps completed';}
async function request(body,id){const r=await fetch('/api/staff/diagnostics'+(id?'?id='+encodeURIComponent(id):''),{credentials:'same-origin',method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined}),data=await r.json();if(!r.ok)throw Error(data.error||'Diagnostic unavailable.');return data;}
function findingBox(f){const box=document.createElement('article');box.className='diagnostic-finding';box.dataset.severity=f.severity;const title=document.createElement('b'),meta=document.createElement('small'),message=document.createElement('p');title.textContent=f.severity.toUpperCase()+' · '+f.category;meta.textContent=f.page;message.textContent=f.message;box.append(title,meta,message);return box;}
function draw(){if(!current)return;$('diagnosticHeading').textContent='Report · '+new Date(current.createdAt).toLocaleString();$('diagnosticStats').replaceChildren();for(const [label,value] of [['Pages audited',current.pages],['Links inspected',current.links],['Errors',current.findings.filter(f=>f.severity==='error').length],['Warnings',current.findings.filter(f=>f.severity==='warning').length]]){const a=document.createElement('article'),b=document.createElement('b'),small=document.createElement('small');b.textContent=value;small.textContent=label;a.append(small,b);$('diagnosticStats').append(a);}$('diagnosticChecks').replaceChildren();for(const check of current.checks){const div=document.createElement('div'),name=document.createElement('span'),status=document.createElement('b'),detail=document.createElement('small');div.className='diagnostic-check';name.textContent=check.name;detail.textContent=check.detail||'';name.append(detail);status.textContent=check.status.toUpperCase();div.append(name,status);$('diagnosticChecks').append(div);}$('diagnosticFindings').replaceChildren();const list=current.findings.filter(f=>!$('diagnosticFilter').value||f.severity===$('diagnosticFilter').value);if(!list.length)$('diagnosticFindings').textContent='No findings in this selection.';for(const f of list)$('diagnosticFindings').append(findingBox(f));$('downloadDiagnostic').disabled=false;}
async function history(){try{const data=await request();$('diagnosticHistory').replaceChildren();for(const row of data.reports){const button=document.createElement('button'),meta=document.createElement('small');button.textContent=row.status.toUpperCase()+' · v'+row.version;meta.textContent=new Date(row.createdAt).toLocaleString()+' · '+row.author;button.append(meta);button.onclick=async()=>{try{current=(await request(null,row.id)).report;draw();}catch(e){$('diagnosticStatus').textContent=e.message;}};$('diagnosticHistory').append(button);}if(!data.reports.length)$('diagnosticHistory').textContent='No saved inspections yet.';}catch(e){$('diagnosticStatus').textContent=e.message;}}
async function sample(page){const frame=document.createElement('iframe');frame.setAttribute('aria-hidden','true');frame.style.cssText='position:absolute;left:-10000px;width:1280px;height:900px;border:0;';const results=[];await new Promise(resolve=>{const timeout=setTimeout(()=>{results.push({severity:'warning',category:'load',page,message:'Page did not finish loading within 12 seconds.'});resolve();},12000);frame.onload=()=>{clearTimeout(timeout);setTimeout(resolve,1200);};frame.src=page;document.body.append(frame);});try{const doc=frame.contentDocument;if(!doc?.body)throw Error('Page inaccessible.');const final=frame.contentWindow.location.pathname;if(final!==page)results.push({severity:'info',category:'load',page,message:'Redirected to '+final+'; requested layout was not inspected.'});else{if(doc.documentElement.scrollWidth>doc.documentElement.clientWidth+3)results.push({severity:'warning',category:'layout',page,message:'Horizontal page overflow at 1280 px. Check wide tables and navigation.'});if(!doc.styleSheets.length)results.push({severity:'error',category:'style',page,message:'No stylesheets loaded.'});for(const img of [...doc.images].filter(e=>e.loading!=='lazy'&&e.complete&&!e.naturalWidth).slice(0,8))results.push({severity:'warning',category:'asset',page,message:'Image could not load: '+new URL(img.src,location.origin).pathname});const log=frame.contentWindow.starfallErrorLog?.text()||'';if(log)results.push({severity:'warning',category:'runtime',page,message:'Errors recorded during this page load: '+log.slice(-300)});const invisible=[...doc.querySelectorAll('button,a,input,textarea,select')].filter(e=>{const s=frame.contentWindow.getComputedStyle(e),r=e.getBoundingClientRect();const closed=e.closest('details:not([open])'),inClosed=closed&&!closed.querySelector(':scope > summary')?.contains(e);return !inClosed&&!e.closest('[hidden],[aria-hidden="true"]')&&r.width>0&&r.height>0&&s.visibility!=='hidden'&&s.display!=='none'&&s.opacity!=='0'&&r.right>doc.documentElement.clientWidth+3;});if(invisible.length)results.push({severity:'warning',category:'layout',page,message:invisible.length+' visible controls extend beyond the viewport: '+invisible.slice(0,5).map(e=>e.id||e.getAttribute('aria-label')||e.textContent.trim().slice(0,60)).join(', ')});}}catch(e){results.push({severity:'warning',category:'load',page,message:e.message});}finally{frame.remove();}return results;}
$('runDiagnostics').onclick=async()=>{const button=$('runDiagnostics');button.disabled=true;try{const pages=$('samplePages').checked?['/portal.html','/manual.html','/profile.html','/staff.html','/staff-directory.html','/round-history.html']:[],observations=[];const total=pages.length+1;let completed=0;progress(0,total,'Preparing diagnostic');for(const page of pages){$('diagnosticStatus').textContent='Inspecting '+page+'…';observations.push(...await sample(page));progress(++completed,total,'Inspected '+page);}progress(completed,total,'Checking publication and saving report');$('diagnosticStatus').textContent='Checking publication integrity and storing report…';current=(await request({observations,sampledPages:pages.length})).report;draw();progress(total,total,'Diagnostic complete · report saved');await history();$('diagnosticStatus').textContent='Report saved · '+current.status.toUpperCase();}catch(e){$('diagnosticStatus').textContent=e.message;$('diagnosticProgressLabel').textContent='Diagnostic stopped · '+e.message;}finally{button.disabled=false;}};
$('diagnosticFilter').onchange=draw;$('downloadDiagnostic').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(current,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='starfall-diagnostic-'+current.id+'.json';a.click();URL.revokeObjectURL(url);};history();})();
